<script setup>
    import { onMounted, ref,inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Workshop Dashboard' });
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const formatNumber = inject('formatNumber')
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const refreshButton = inject('refreshButton')
    const loading = ref(false)
    const waitIndicator = inject('waitIndicator')
    const rowShimmer = inject('rowShimmer')
    const tableShimmer = inject('tableShimmer')
    const showMessage = inject('showMessage')
    const activeTab = ref(3)
    const openTab = (tab) =>{
       activeTab.value = tab
    }


    const columns = ref(['SNo', 'jobcard','asset','odometer','issuer','location', 'date', 'status']);
    const table_option = ref({
        perPage: 10,
        perPageValues: [10, 20, 50],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const miniBar  = ref(true)

    const masterServices = ref([])
    const getMasterServices = async ()  => {
        loading.value = true
        try{
          const response = await  axiosInstance.get('/master-services')
          masterServices.value = response.data
        }finally{
            loading.value = false
        }
    };


const formData = ref({
    tasks : [],
    materials : [],
    services : []
})

const tasks = ref([])
const materials = ref([])
const services = ref([])
const editable = ref('')


const currentStep = ref(0)

const nextStep = () => {
    if (currentStep.value < 2) {
        currentStep.value++
    }
}

const prevStep = () => {
    if (currentStep.value > 0) {
        currentStep.value--
    }
}

const showStep = (step) => {
    return currentStep.value === step
}

const getRawData = async()=>{
    const response = await axiosInstance.get('/master-service-raw-data')
    tasks.value = response.data.tasks
    materials.value = response.data.materials.map((item)=>({
        ...item,
        quantity : '',
        item_id : item.id
    })),
    services.value = response.data.services
}

const showError = inject('showError')
const loadingSpinner = inject('loadingIndicator')
const selectedService = ref('')
const saveMasterServices = async ()=>{
    loading.value = true
    const payload = {
        materials : formData.value.materials,
        services : formData.value.services,
        tasks : formData.value.tasks,
        name : formData.value.name,
        description :formData.value.description
    }
    try{
        await axiosInstance.post('/master-services',payload)
        showMessage('Data Saved')
        document.getElementById('close-register').click()
        getRawData()
        getMasterServices()
    }catch(error){
        console.log(error)
        showError(error.message)
    }finally{
      loading.value = false
    }
}

const selectService = (service) =>{
  selectedService.value = service
}

const editService = (service) =>{
  selectedService.value = service
  formData.value.name = service.name,
  formData.value.description = service.description
  formData.value.tasks = service.activities.map((item)=>({
    ...item,
    name : item.item.name
  }))

  formData.value.services = service.included_services.map((item)=>({
    ...item,
    name : item.service.name
  }))


    formData.value.materials = service.spares.map((item)=>({
    ...item,
    name : item.item.name,
    quantity : item.qty
  }))

  document.getElementById('add-edit').click()
}
    onMounted(() => {
      getMasterServices()
    });
</script>

<style scoped>
        .step {
            display: none;
        }

        .step.active {
            display: block;
        }

        .step-indicator {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background: #dee2e6;
            color: #000;
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
            cursor: pointer;
        }

.step-indicator.active {
   background: #0d6efd; /* green - completed steps */
    color: #fff;
}

.step-indicator.current {
      /* blue - current step */
      background: #28a745;  
    color: #fff;
}

        .line {
            flex: 1;
            height: 3px;
            background: #dee2e6;
        }

        
        .service-tab {
  text-align: center;
  cursor: pointer;

  .item {
    padding: 4px 8px;
    border-bottom: 5px solid transparent; /* prevents layout shift on hover */
    transition: border-color 0.2s;
  }

  .item:hover {
    border-bottom: 5px solid rgb(141, 182, 221);
  }

  .active {
    border-bottom: 5px solid #1D6CE3;
  }
}

    </style>



